import * as THREE from 'three';
import type { WorldCollider, WorldParts } from './world';
import { terrainHeight } from './world';

export class PlayerMotor {
  readonly velocity = new THREE.Vector3();
  grounded = false;
  private verticalVelocity = 0;
  constructor(private root: THREE.Group, private colliders: WorldCollider[]) {}

  update(delta: number, moveForward: number, moveSide: number, sprint: boolean, jump: boolean, facingYaw: number, flight = false, verticalInput = 0, cameraPitch = 0) {
    const inputLength = Math.hypot(moveForward, moveSide);
    let desiredX = 0, desiredZ = 0;
    if (inputLength > 0) {
      const fX = -Math.sin(facingYaw), fZ = -Math.cos(facingYaw);
      const rX = Math.cos(facingYaw), rZ = -Math.sin(facingYaw);
      desiredX = (fX * moveForward + rX * moveSide) / inputLength;
      desiredZ = (fZ * moveForward + rZ * moveSide) / inputLength;
      const speed = flight ? (sprint ? 7.6 : 5.2) : (sprint ? 7.4 : 4.35);
      desiredX *= speed; desiredZ *= speed;
    }
    const response = inputLength > 0 ? 16 : 20;
    this.velocity.x = THREE.MathUtils.damp(this.velocity.x, desiredX, response, delta);
    this.velocity.z = THREE.MathUtils.damp(this.velocity.z, desiredZ, response, delta);

    const steps = Math.max(1, Math.ceil(Math.hypot(this.velocity.x, this.velocity.z) * delta / .22));
    const stepDelta = delta / steps;
    for (let step = 0; step < steps; step++) {
      let x = this.root.position.x + this.velocity.x * stepDelta;
      let z = this.root.position.z + this.velocity.z * stepDelta;
      x = THREE.MathUtils.clamp(x, -105, 105); z = THREE.MathUtils.clamp(z, -105, 105);
      for (const collider of this.colliders) {
        let dx = x - collider.x, dz = z - collider.z;
        const minimum = collider.radius + .31;
        const distance = Math.hypot(dx, dz);
        if (distance < minimum) {
          if (distance < .0001) { dx = .001; dz = 0; }
          const length = Math.hypot(dx, dz);
          x = collider.x + (dx / length) * minimum;
          z = collider.z + (dz / length) * minimum;
          const normalVelocity = this.velocity.x * (dx / length) + this.velocity.z * (dz / length);
          if (normalVelocity < 0) {
            this.velocity.x -= normalVelocity * (dx / length);
            this.velocity.z -= normalVelocity * (dz / length);
          }
        }
      }
      this.root.position.x = x; this.root.position.z = z;
    }

    const surfaceY = terrainHeight(this.root.position.x, this.root.position.z);
    if (flight) {
      const forwardLift = -moveForward * Math.sin(cameraPitch) * (sprint ? 7.6 : 5.2);
      this.verticalVelocity = THREE.MathUtils.damp(this.verticalVelocity, verticalInput * 4.4 + forwardLift, 8, delta);
      this.root.position.y = Math.max(surfaceY + .12, this.root.position.y + this.verticalVelocity * delta);
      this.grounded = false;
    } else if (this.root.position.y <= surfaceY + .06 && this.verticalVelocity <= 0) {
      this.root.position.y = surfaceY;
      this.verticalVelocity = 0;
      this.grounded = true;
    } else this.grounded = false;
    if (!flight && jump && this.grounded) {
      this.verticalVelocity = 9.4;
      this.grounded = false;
    }
    if (!flight) { this.verticalVelocity -= 26 * delta; this.root.position.y += this.verticalVelocity * delta; }
    if (!flight && this.root.position.y <= surfaceY) {
      this.root.position.y = surfaceY;
      this.verticalVelocity = 0;
      this.grounded = true;
    }

    if (inputLength > 0 && Math.hypot(this.velocity.x, this.velocity.z) > .2) {
      const facing = Math.atan2(this.velocity.x, this.velocity.z);
      this.root.userData.facing = facing;
    }
    return inputLength > 0 && Math.hypot(this.velocity.x, this.velocity.z) > .35;
  }
}

export class ThirdPersonCamera {
  yaw = 0;
  pitch = .19;
  distance = 7.4;
  sensitivity = .0032;
  private currentDistance = 7.4;
  private readonly raycaster = new THREE.Raycaster();
  private readonly target = new THREE.Vector3();
  private readonly offset = new THREE.Vector3();
  private readonly desired = new THREE.Vector3();
  private readonly look = new THREE.Vector3();
  private collisionDistance = 7.4;
  private readonly collisionObjects: THREE.Object3D[];

  constructor(private camera: THREE.PerspectiveCamera, private parts: WorldParts) {
    this.collisionObjects = parts.blockers;
  }

  rotate(dx: number, dy: number) {
    this.yaw -= dx * this.sensitivity;
    this.pitch = THREE.MathUtils.clamp(this.pitch + dy * this.sensitivity, -.12, .72);
  }

  zoom(delta: number) {
    this.distance = THREE.MathUtils.clamp(this.distance + delta * .008, 3.4, 13.5);
  }

  update(root: THREE.Group, delta: number) {
    this.target.set(root.position.x, root.position.y + 1.48, root.position.z);
    const horizontal = Math.cos(this.pitch) * this.distance;
    this.offset.set(Math.sin(this.yaw) * horizontal, Math.sin(this.pitch) * this.distance + .48, Math.cos(this.yaw) * horizontal);
    this.desired.copy(this.target).add(this.offset);
    this.raycaster.near = .1;
    this.raycaster.far = this.distance;
    this.raycaster.set(this.target, this.offset.clone().normalize());
    const hit = this.raycaster.intersectObjects(this.collisionObjects, true).find(item => item.distance < this.distance - .2);
    const requestedDistance = hit ? Math.max(.8, hit.distance - .36) : this.distance;
    if (requestedDistance < this.collisionDistance) this.collisionDistance = requestedDistance;
    else this.collisionDistance = THREE.MathUtils.damp(this.collisionDistance, requestedDistance, 7, delta);
    this.currentDistance = THREE.MathUtils.damp(this.currentDistance, this.collisionDistance, 18, delta);
    this.look.copy(this.target).add(new THREE.Vector3(-Math.sin(this.yaw) * 12, 1.05, -Math.cos(this.yaw) * 12));
    this.desired.copy(this.offset).setLength(this.currentDistance).add(this.target);
    this.desired.y = Math.max(this.desired.y, terrainHeight(this.desired.x, this.desired.z) + .85);
    this.camera.position.lerp(this.desired, 1 - Math.exp(-delta * 12));
    this.camera.lookAt(this.look);
  }

  getAimPoint(out: THREE.Vector3, extraTargets: THREE.Object3D[] = []) {
    this.camera.updateMatrixWorld();
    this.raycaster.setFromCamera(new THREE.Vector2(0, 0), this.camera);
    this.raycaster.near = .1;
    this.raycaster.far = 30;
    const hit = this.raycaster.intersectObjects([...this.parts.blockers, this.parts.ground, ...extraTargets], true)[0];
    if (hit) out.copy(hit.point);
    else this.raycaster.ray.at(30, out);
    return out;
  }
}
