import * as THREE from 'three';
import { terrainHeight } from './world';

type Wisp = { root: THREE.Group; health: number; phase: number; shot: number };
type Shot = { mesh: THREE.Mesh; velocity: THREE.Vector3; age: number };

/** Small original training enemies make spell damage and defensive play part of the world. */
export class CombatSystem {
  readonly targets: THREE.Object3D[] = [];
  readonly playerHealth = 100;
  health = 100;
  blocked = 0;
  private wisps: Wisp[] = [];
  private shots: Shot[] = [];
  private root = new THREE.Group();
  private readonly coreGeo = new THREE.IcosahedronGeometry(.55, 1);
  private readonly coreMat = new THREE.MeshStandardMaterial({ color: '#667d75', emissive: '#344d45', emissiveIntensity: .55, roughness: .45, metalness: .2 });
  private readonly shotGeo = new THREE.SphereGeometry(.14, 10, 8);
  private readonly shotMat = new THREE.MeshBasicMaterial({ color: '#d98b6b' });
  constructor(private scene: THREE.Scene, private onSentinelDefeated: () => void = () => {}) {
    this.root.name = 'echo-sentinels'; scene.add(this.root);
    for (const [x, z] of [[-4, -22], [0, -25], [4, -22]]) {
      const group = new THREE.Group(); group.position.set(x, terrainHeight(x, z) + 2.2, z); this.root.add(group);
      const core = new THREE.Mesh(this.coreGeo, this.coreMat); core.name = 'sentinel-target'; group.add(core); this.targets.push(core);
      const ring = new THREE.Mesh(new THREE.TorusGeometry(.83, .035, 7, 24), new THREE.MeshBasicMaterial({ color: '#aebf99', transparent: true, opacity: .58 })); ring.rotation.x = Math.PI / 2; group.add(ring);
      const halo = new THREE.PointLight('#b4c89a', .6, 4); group.add(halo);
      this.wisps.push({ root: group, health: 100, phase: Math.random() * 6, shot: 2.3 + Math.random() * 1.6 });
    }
  }
  get alive() { return this.wisps.filter(w => w.health > 0).length; }
  damageAt(point: THREE.Vector3, radius: number, damage: number) {
    let count = 0;
    for (const wisp of this.wisps) if (wisp.health > 0 && wisp.root.position.distanceTo(point) <= radius + .65) { wisp.health = Math.max(0, wisp.health - damage); count++; if (!wisp.health) { wisp.root.visible = false; this.onSentinelDefeated(); } }
    return count;
  }
  update(delta: number, elapsed: number, player: THREE.Vector3, block: (from: THREE.Vector3, to: THREE.Vector3) => boolean) {
    for (const wisp of this.wisps) if (wisp.health > 0) {
      wisp.root.position.y += Math.sin(elapsed * 1.7 + wisp.phase) * delta * .35;
      wisp.root.rotation.y += delta * .45;
      wisp.shot -= delta;
      if (wisp.shot <= 0 && wisp.root.position.distanceTo(player) < 26) {
        wisp.shot = 3.6 + Math.random() * 1.5;
        const mesh = new THREE.Mesh(this.shotGeo, this.shotMat); mesh.position.copy(wisp.root.position); this.root.add(mesh);
        const dir = player.clone().add(new THREE.Vector3(0, 1, 0)).sub(mesh.position).normalize();
        this.shots.push({ mesh, velocity: dir.multiplyScalar(7.8), age: 0 });
      }
    }
    for (let i = this.shots.length - 1; i >= 0; i--) {
      const shot = this.shots[i], from = shot.mesh.position.clone(); shot.age += delta; shot.mesh.position.addScaledVector(shot.velocity, delta);
      if (block(from, shot.mesh.position)) { shot.mesh.removeFromParent(); this.shots.splice(i, 1); this.blocked++; continue; }
      if (shot.mesh.position.distanceTo(player.clone().add(new THREE.Vector3(0, 1, 0))) < .66) { this.health = Math.max(0, this.health - 12); shot.age = 5; }
      if (shot.age > 4 || shot.mesh.position.y < terrainHeight(shot.mesh.position.x, shot.mesh.position.z)) { shot.mesh.removeFromParent(); this.shots.splice(i, 1); }
    }
  }
  dispose() { this.root.removeFromParent(); this.coreGeo.dispose(); this.coreMat.dispose(); this.shotGeo.dispose(); this.shotMat.dispose(); this.root.traverse(o => { if (o instanceof THREE.Mesh && o.material !== this.coreMat && o.material !== this.shotMat) { o.geometry.dispose(); if (Array.isArray(o.material)) o.material.forEach(m => m.dispose()); else o.material.dispose(); } }); }
}
